import json
class D(json.JSONDecoder):
 def __init__(self,tag,**kw):
  print("init",tag)
  super().__init__(**kw)
 def decode(self,s):
  print(type(s).__name__,repr(s))
  return super().decode(s)
print(json.loads(b"7",cls=D,tag="t"))

